  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:
    """
    Clean and transform the raw Fair (affairs) dataset into a dataframe with the columns
    needed for modelling: AffairCount, HasChildren, Age, YearsMarried, Education,
    Religiousness, Occupation, MaritalSatisfaction.

    The original dataset has some inconsistent/descriptive metadata; this function
    (1) robustly identifies the column that indicates presence of children (checks
        both 'children' and 'age' because dataset metadata is inconsistent),
    (2) coerces the affairs column to numeric (AffairCount),
    (3) coerces controls to numeric and drops rows with missing critical values.

    Returns the dataframe with only the required columns for modelling.
    """
    df = df.copy()

    # 1) Create AffairCount from the 'affairs' column (coerce to numeric)
    df['AffairCount'] = pd.to_numeric(df.get('affairs'), errors='coerce')

    # 2) Infer which column encodes whether there are children in the marriage.
    # Some metadata versions have this in 'children' (yes/no) or in 'age' (yes/no) due to mislabeling.
    children_col = None
    for cand in ['children', 'age']:
        if cand in df.columns:
            vals = df[cand].dropna().astype(str).str.lower().unique()
            vals_set = set([v.strip() for v in vals if isinstance(v, str)])
            # look for yes/no-like strings
            if {'yes', 'no'}.intersection(vals_set):
                children_col = cand
                break
            # numeric 0/1 indicator
            try:
                numeric_vals = pd.to_numeric(df[cand].dropna(), errors='coerce')
                unique_numeric = set(np.unique(numeric_vals.dropna()))
                if unique_numeric.issubset({0.0, 1.0}):
                    children_col = cand
                    break
            except Exception:
                pass

    # If not found yet, fallback to using 'children' if it exists (numeric >0 -> has children)
    if children_col is None and 'children' in df.columns:
        # attempt numeric interpretation
        try:
            numeric_vals = pd.to_numeric(df['children'], errors='coerce')
            if numeric_vals.notna().sum() > 0:
                children_col = 'children'
        except Exception:
            children_col = 'children'

    # Build HasChildren column robustly
    def map_to_has_children(series: pd.Series) -> pd.Series:
        s = series.copy()
        # strings
        if s.dtype == object or s.dtype.name == 'category':
            s_str = s.astype(str).str.strip().str.lower()
            # common yes/no
            s_mapped = s_str.replace({'yes': 1, 'y': 1, 'true': 1, '1': 1, 'no': 0, 'n': 0, 'false': 0, '0': 0})
            # if values are male/female, we cannot map: return NaN
            if set(s_str.unique()).issubset({'male', 'female', 'm', 'f'}):
                return pd.Series([np.nan] * len(s), index=s.index)
            return pd.to_numeric(s_mapped, errors='coerce')
        else:
            # numeric: treat >0 as having children, 0 as no children
            s_num = pd.to_numeric(s, errors='coerce')
            return (s_num > 0).astype(float)

    if children_col is not None:
        df['HasChildren'] = map_to_has_children(df[children_col])
    else:
        # if we cannot find a children indicator, create column of NaNs (will be dropped later)
        df['HasChildren'] = np.nan

    # 3) Controls: coerce relevant columns to numeric with sensible names
    # 'rating' in this dataset is the age coding (17.5,22,...)
    if 'rating' in df.columns:
        df['Age'] = pd.to_numeric(df['rating'], errors='coerce')
    else:
        df['Age'] = np.nan

    # Years married: prefer explicit 'yearsmarried' column
    if 'yearsmarried' in df.columns:
        df['YearsMarried'] = pd.to_numeric(df['yearsmarried'], errors='coerce')
    else:
        # some metadata versions store it in 'gender' column; attempt to coerce if plausible
        if 'gender' in df.columns:
            df['YearsMarried'] = pd.to_numeric(df['gender'], errors='coerce')
        else:
            df['YearsMarried'] = np.nan

    # Education
    if 'education' in df.columns:
        df['Education'] = pd.to_numeric(df['education'], errors='coerce')
    else:
        df['Education'] = np.nan

    # Religiousness
    if 'religiousness' in df.columns:
        df['Religiousness'] = pd.to_numeric(df['religiousness'], errors='coerce')
    else:
        df['Religiousness'] = np.nan

    # Occupation (numeric code)
    if 'occupation' in df.columns:
        df['Occupation'] = pd.to_numeric(df['occupation'], errors='coerce')
    else:
        df['Occupation'] = np.nan

    # Marital satisfaction is stored in 'rownames' in this schema
    if 'rownames' in df.columns:
        df['MaritalSatisfaction'] = pd.to_numeric(df['rownames'], errors='coerce')
    else:
        df['MaritalSatisfaction'] = np.nan

    # 4) Drop rows missing key model variables: AffairCount or HasChildren
    df = df.dropna(subset=['AffairCount', 'HasChildren'])

    # 5) Ensure integer count for AffairCount (if it's not integer, keep numeric but round if close to integer)
    # We'll keep AffairCount as numeric (counts) for count models; enforce non-negative
    df['AffairCount'] = pd.to_numeric(df['AffairCount'], errors='coerce')
    df = df[df['AffairCount'].notna()]
    # remove negative values if any
    df = df[df['AffairCount'] >= 0]

    # Final dataframe keeps only the columns needed for modeling
    final_cols = [
        'AffairCount', 'HasChildren', 'Age', 'YearsMarried', 'Education',
        'Religiousness', 'Occupation', 'MaritalSatisfaction'
    ]
    # If any of the control columns are not present in the input, they will be present as NaN - the model will handle / drop them
    return df[final_cols]
